"""Independent small finite-image and Schreier certificates (#42)."""

import pytest
from sage.matrix.constructor import matrix
from sage.matrix.special import identity_matrix
from sage.modules.free_module_element import vector
from sage.rings.integer_ring import ZZ

from sage_indefinite_port.indefinite.congruence_images import IntegralCongruenceImage


def test_composite_level_actual_image_and_kernel():
    # O(U) generated by swapping isotropic axes and simultaneous negation.
    swap = matrix(ZZ, [[0, 1], [1, 0]])
    negative = -identity_matrix(ZZ, 2)
    for modulus in (2, 4, 6):
        image = IntegralCongruenceImage((swap, negative), modulus)
        assert len(image.image_keys()) == (2 if modulus == 2 else 4)
        index, kernel = image.preimage_generators((image.image_one,))
        assert index == len(image.image_keys())
        assert all(g.change_ring(image.ring) == image.image_one for g in kernel)
        assert all(g.transpose() * swap * g == swap for g in kernel)


def test_nonnormal_subgroup_preimage_uses_schreier_not_generator_filter():
    # Permutation matrices generate S_3, and a transposition subgroup has index 3.
    a = matrix(ZZ, [[0, 1, 0], [1, 0, 0], [0, 0, 1]])
    b = matrix(ZZ, [[1, 0, 0], [0, 0, 1], [0, 1, 0]])
    image = IntegralCongruenceImage((a, b), 4)
    assert len(image.image_keys()) == 6
    index, generators = image.preimage_generators((image.image_one, image.reduce(a)))
    assert index == 3
    assert generators
    assert all(image._key(image.reduce(g)) in {image._key(image.image_one), image._key(image.reduce(a))} for g in generators)
    assert any(image.reduce(g) == image.reduce(a) for g in generators)


def test_rejects_non_subgroup_and_nonunimodular_inputs():
    a = matrix(ZZ, [[0, 1], [1, 0]])
    image = IntegralCongruenceImage((a,), 3)
    with pytest.raises(ValueError):
        image.preimage_generators(())
    with pytest.raises(ValueError):
        IntegralCongruenceImage((2 * identity_matrix(ZZ, 2),), 3)


def test_residue_vector_stabilizer_uses_actual_image():
    a = matrix(ZZ, [[0, 1], [1, 0]])
    negative = -identity_matrix(ZZ, 2)
    image = IntegralCongruenceImage((a, negative), 4)
    index, stabilizer = image.residue_vector_stabilizer((1, 0))
    assert index == 4
    point = vector(image.ring, (1, 0))
    assert all(g.change_ring(image.ring) * point == point for g in stabilizer)
    index_zero, whole = image.residue_vector_stabilizer((0, 0))
    assert index_zero == 1
    assert whole


def test_lattice_consumer_returns_integral_isometries_at_composite_level():
    from tests.acceptance.consumer import lattice
    from sage_indefinite_port.indefinite.recursive import EichlerRecursion

    ambient = lattice([[0, 1], [1, 0]])
    engine = EichlerRecursion()
    image = engine.congruence_image(ambient, 4)
    assert len(image.image_keys()) == 4
    index, stabilizer = engine.congruence_stabilizer_generators(ambient, 4, (1, 0))
    assert index == 4
    for g in stabilizer:
        assert g.domain() is ambient and g.codomain() is ambient
        assert tuple(int(x) % 4 for x in g(ambient.module_generators()[0]).to_vector()) == (1, 0)


def test_nonfree_composite_residue_submodule_stabilizer():
    swap = matrix(ZZ, [[0, 1], [1, 0]])
    negative = -identity_matrix(ZZ, 2)
    image = IntegralCongruenceImage((swap, negative), 4)
    # The order-two submodule generated by (2,0) is not a free Z/4 summand.
    index, generators = image.residue_submodule_stabilizer(((2, 0),))
    assert index == 2
    point = vector(image.ring, (2, 0))
    assert all(g.change_ring(image.ring) * point == point for g in generators)
    index_full, _ = image.residue_submodule_stabilizer(((1, 0), (0, 1)))
    assert index_full == 1


