def test_joint_discriminant_level_determinant_and_field_spinor_preimage():
    """For <6>, all nontrivial characters come from the same -1 coset."""
    from tests.acceptance.consumer import lattice
    from sage_indefinite_port.indefinite.recursive import EichlerRecursion

    ambient = lattice([[6]])
    engine = EichlerRecursion()
    image = engine.joint_discriminant_character_image(
        ambient, determinant=True, field_spinor=True, level_modulus=2
    )
    minus = matrix(ZZ, [[-1]])
    assert len(image.image_keys()) == 2  # O(<6>) = {+1, -1}, not a product of characters.
    assert image.image(minus)[0] == image.identity[0]  # -1 is trivial mod 2.
    assert image.image(minus)[1] != image.identity[1]  # Nontrivial on Z/6Z.
    assert image.image(minus)[2] == -1
    assert image.image(minus)[3] != image.identity[3]  # Nontrivial rational spinor class.
    assert image.image(image.section(image.image(minus))) == image.image(minus)
    allowed = image.subgroup_from_membership(lambda key: key[3] == image.identity[3])
    assert allowed == frozenset((image.identity,))
    index, kernel = engine.joint_discriminant_character_preimage_generators(
        ambient, allowed, determinant=True, field_spinor=True, level_modulus=2
    )
    assert index == 2
    assert all(g.domain() is ambient and g.codomain() is ambient for g in kernel)
    assert all(image.image(matrix(ZZ, [list(g(x).to_vector()) for x in ambient.module_generators()]).transpose()) == image.identity for g in kernel)


def test_preimage_membership_rejects_elements_outside_generated_ambient_subgroup():
    """The trivial discriminant action of O(U) must not erase G=<minus I>."""
    from tests.acceptance.consumer import lattice
    from sage_indefinite_port.indefinite.recursive import EichlerRecursion

    ambient = lattice([[0, 1], [1, 0]])
    e, f = ambient.module_generators()
    minus = ambient.O()((-e, -f))
    image = EichlerRecursion().joint_discriminant_character_image(
        ambient, ambient_generators=(minus,)
    )
    assert image.image_keys() == frozenset((image.identity,))  # A_U = 0.
    assert image.preimage_membership(matrix(ZZ, [[-1, 0], [0, -1]]), (image.identity,))
    assert not image.preimage_membership(matrix(ZZ, [[0, 1], [1, 0]]), (image.identity,))


def test_public_joint_character_preimage_is_owned_subgroup_with_generators():
    """The determinant kernel O(U) has two elements and index two."""
    from tests.acceptance.consumer import lattice
    from sage_indefinite_port.indefinite.recursive import EichlerRecursion

    ambient = lattice([[0, 1], [1, 0]])
    e, f = ambient.module_generators()
    minus = ambient.O()((-e, -f))
    swap = ambient.O()((f, e))
    engine = EichlerRecursion()
    image = engine.joint_discriminant_character_image(ambient, determinant=True)
    subgroup = engine.joint_discriminant_character_preimage_subgroup(
        ambient, iter((image.identity,)), determinant=True,
    )
    assert subgroup.supergroup() is ambient.O()
    assert ambient.O().one() in subgroup and minus in subgroup
    assert swap not in subgroup
    selected = tuple(subgroup.group_generators())
    assert selected and all(g in subgroup for g in selected)
    assert ambient.O().subgroup(selected).cardinality() == 2


def test_joint_preimage_subgroup_retains_proper_generated_ambient_group():
    """A trivial quotient restriction must return G, not the larger O(U)."""
    from tests.acceptance.consumer import lattice
    from sage_indefinite_port.indefinite.recursive import EichlerRecursion

    ambient = lattice([[0, 1], [1, 0]])
    e, f = ambient.module_generators()
