def test_number_field_base_changed_spinor_is_an_actual_finite_image_preimage():
    """The nontrivial image of sn_{Q(sqrt 5)} on O(<6>) has order two."""
    from sage_extensions.all import QuadraticField, QQ as OwnedQQ
    from tests.acceptance.consumer import lattice
    from sage_indefinite_port.indefinite.recursive import EichlerRecursion

    field = QuadraticField(5, "a")
    embedding = OwnedQQ.Mor(field)(lambda x: field(x))
    ambient = lattice([[6]])
    engine = EichlerRecursion()
    image = engine.joint_discriminant_character_image(
        ambient, field_spinor=True, field_map=embedding,
    )
    minus = matrix(ZZ, [[-1]])
    assert len(image.image_keys()) == 2
    assert image.image(minus)[-1] == field.square_class_group()(field(-3))
    subgroup = engine.joint_discriminant_character_preimage_subgroup(
        ambient, (image.identity,), field_spinor=True, field_map=embedding,
    )
    assert int(subgroup.preimage_morphism().codomain().cardinality()) == 2
    assert int(subgroup.index()) == 2
    assert ambient.O().one() in subgroup
    assert ambient.O()((-ambient.module_generators()[0],)) not in subgroup


def test_owned_preimage_index_is_relative_to_proper_generated_ambient():
    """G=<swap> in O(U), det G=C2; its det kernel is trivial, with [G:1]=2."""
    from tests.acceptance.consumer import lattice
    from sage_indefinite_port.indefinite.recursive import EichlerRecursion

    ambient = lattice([[0, 1], [1, 0]])
    e, f = ambient.module_generators()
    swap = ambient.O()((f, e))
    minus = ambient.O()((-e, -f))
    engine = EichlerRecursion()
    image = engine.joint_discriminant_character_image(
        ambient, determinant=True, ambient_generators=(swap,),
    )
    assert len(image.image_keys()) == 2
    subgroup = engine.joint_discriminant_character_preimage_subgroup(
        ambient, (image.identity,), determinant=True, ambient_generators=(swap,),
    )
    assert int(subgroup.preimage_morphism().codomain().cardinality()) == 2
    assert int(subgroup.index()) == 2
    assert int(subgroup.cardinality()) == 1
    assert ambient.O().one() in subgroup
    assert swap not in subgroup and minus not in subgroup


def test_joint_discriminant_right_coset_action_respects_multiplication():
    from tests.acceptance.consumer import lattice
    from sage_indefinite_port.indefinite.recursive import EichlerRecursion

    ambient = lattice([[0, 2], [2, 0]])
    image = EichlerRecursion().joint_discriminant_character_image(
        ambient, determinant=True, real_spinor=True, level_modulus=4
    )
    subgroup = image.subgroup_from_membership(lambda key: key[2] == 1)
    cosets, act = image.right_coset_action(subgroup)
    assert len(cosets) * len(subgroup) == len(image.image_keys())
    assert len(cosets) == 2
    lifts = tuple(image.section(key) for key in image.image_keys())
    for i in range(len(cosets)):
        for g in lifts:
            for h in lifts:
                assert act(act(i, g), h) == act(i, g * h)
    assert all(act(0, g) == 0 for g in image.preimage_generators(subgroup)[1])


def test_joint_discriminant_right_coset_transporter_has_verified_integral_witness():
    from tests.acceptance.consumer import lattice
    from sage_indefinite_port.indefinite.recursive import EichlerRecursion

    ambient = lattice([[0, 2], [2, 0]])
    image = EichlerRecursion().joint_discriminant_character_image(
        ambient, determinant=True, real_spinor=True, level_modulus=4
    )
    subgroup = image.subgroup_from_membership(lambda key: key[2] == 1)
    cosets, act = image.right_coset_action(subgroup)
    for i in range(len(cosets)):
        for j in range(len(cosets)):
            witness = image.right_coset_transporter(subgroup, i, j)
            assert abs(witness.det()) == 1
            assert act(i, witness) == j


def test_joint_finite_double_cosets_and_intersections():
    from tests.acceptance.consumer import lattice
    from sage_indefinite_port.indefinite.recursive import EichlerRecursion

    ambient = lattice([[0, 2], [2, 0]])
    image = EichlerRecursion().joint_discriminant_character_image(
        ambient, determinant=True, real_spinor=True, level_modulus=4
    )
    left = image.subgroup_from_membership(lambda key: key[2] == 1)
    right = image.subgroup_from_membership(lambda key: key[3] == 1)
    representatives = image.double_coset_representatives(left, right)
    assert representatives
    covered = set()
    for key, witness in representatives:
        assert image.image(witness) == key
        orbit = {image._multiply(image._multiply(h, key), k) for h in left for k in right}
        assert not covered.intersection(orbit)
        covered.update(orbit)
        intersection = image.double_coset_intersection(left, right, key)
        assert len(orbit) * len(intersection) == len(left) * len(right)
    assert covered == image.image_keys()
